/**
 * Emulation of the CPython exception objects and traceback rendering that the
 * original script can produce.
 *
 * Only the pieces reachable from `test12.py` are modelled: `UnicodeEncodeError`
 * (raised by `str.encode('ascii')`) and `ValueError` (raised by `int()`).
 */

/** Base class for every emulated CPython exception. */
export class PyException extends Error {
  constructor(pyName, pyMessage) {
    super(pyMessage);
    this.pyName = pyName;
    this.pyMessage = pyMessage;
  }

  /** The final `ExceptionName: message` line of a traceback. */
  formatExceptionOnly() {
    return this.pyMessage === '' ? this.pyName : `${this.pyName}: ${this.pyMessage}`;
  }
}

/** `ValueError`, used by the `int()` conversion. */
export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

/**
 * `UnicodeEncodeError`.
 *
 * CPython does not build the message eagerly; `UnicodeEncodeError.__str__`
 * derives it from the stored fields, always rendering the offending character
 * in escaped form (never as the literal character) and always in lowercase hex.
 */
export class PyUnicodeEncodeError extends PyException {
  constructor(encoding, object, start, end, reason) {
    super('UnicodeEncodeError', formatUnicodeEncodeError(encoding, object, start, end, reason));
    this.encoding = encoding;
    this.object = object;
    this.start = start;
    this.end = end;
    this.reason = reason;
  }
}

/**
 * Mirrors `UnicodeEncodeError_str` from CPython's `Objects/exceptions.c`:
 * a single offending code point is quoted with a `\x`/`\u`/`\U` escape whose
 * width depends on its magnitude, a run of them is reported as a range.
 */
function formatUnicodeEncodeError(encoding, object, start, end, reason) {
  if (end === start + 1) {
    const codePoint = [...object][start].codePointAt(0);
    let escaped;
    if (codePoint <= 0xff) {
      escaped = `\\x${codePoint.toString(16).padStart(2, '0')}`;
    } else if (codePoint <= 0xffff) {
      escaped = `\\u${codePoint.toString(16).padStart(4, '0')}`;
    } else {
      escaped = `\\U${codePoint.toString(16).padStart(8, '0')}`;
    }
    return `'${encoding}' codec can't encode character '${escaped}' in position ${start}: ${reason}`;
  }
  return `'${encoding}' codec can't encode characters in position ${start}-${end - 1}: ${reason}`;
}

/**
 * Renders a CPython traceback for `exc` over `frames` and returns it as a
 * string, including the trailing newline that `sys.excepthook` emits.
 *
 * Each frame is `{ file, line, text, caretColumn, caretLength }`, where the
 * caret fields describe the sub-expression CPython underlines (PEP 657).
 */
export function formatTraceback(frames, exc) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name ?? '<module>'}`);
    lines.push(`    ${frame.text}`);
    if (frame.caretLength > 0) {
      lines.push(`    ${' '.repeat(frame.caretColumn)}${'^'.repeat(frame.caretLength)}`);
    }
  }
  lines.push(exc.formatExceptionOnly());
  return `${lines.join('\n')}\n`;
}

