/**
 * CPython's `int(str)` conversion.
 *
 * Python integers are unbounded, so the result is a BigInt: the source script
 * round-trips `--c` through bencode, and values beyond 2**53 must survive.
 */

import { PyValueError } from './errors.mjs';

/** Code points CPython's `Py_UNICODE_ISSPACE` treats as whitespace. */
const PY_SPACE = /[\t\n\v\f\r -   -     　]/u;

const DECIMAL_DIGIT = /\p{Nd}/u;

/**
 * Decimal value of a code point, or -1 when it is not a decimal digit.
 *
 * `int()` accepts every Unicode decimal digit, not just ASCII (`int('١٢٣')` is
 * 123). Every `Nd` block is a contiguous run of ten code points, so walking
 * back to the block's zero yields the digit's value.
 */
function decimalValue(ch) {
  if (!DECIMAL_DIGIT.test(ch)) return -1;
  const cp = ch.codePointAt(0);
  for (let value = 0; value <= 9; value += 1) {
    const candidate = String.fromCodePoint(cp - value);
    if (!DECIMAL_DIGIT.test(candidate)) return -1;
    if (candidate === '0' || isBlockZero(cp - value)) return value;
  }
  return -1;
}

/** A block zero is an `Nd` code point whose predecessor is not one. */
function isBlockZero(cp) {
  if (cp === 0) return false;
  return !DECIMAL_DIGIT.test(String.fromCodePoint(cp - 1));
}

/**
 * Converts `text` the way `int(text)` does, raising `PyValueError` on failure.
 *
 * Accepts surrounding whitespace, an optional sign, and single underscores
 * used as digit separators (`1_000`), but rejects leading, trailing, or
 * doubled underscores.
 */
export function pyInt(text) {
  const chars = [...text];

  let start = 0;
  let end = chars.length;
  while (start < end && PY_SPACE.test(chars[start])) start += 1;
  while (end > start && PY_SPACE.test(chars[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (chars[start] === '+' || chars[start] === '-')) {
    negative = chars[start] === '-';
    start += 1;
  }

  let digits = '';
  let previousWasUnderscore = true; // forbids a leading underscore
  for (let i = start; i < end; i += 1) {
    const ch = chars[i];
    if (ch === '_') {
      if (previousWasUnderscore) throw invalidLiteral(text);
      previousWasUnderscore = true;
      continue;
    }
    const value = decimalValue(ch);
    if (value < 0) throw invalidLiteral(text);
    digits += String(value);
    previousWasUnderscore = false;
  }

  if (digits === '' || previousWasUnderscore) throw invalidLiteral(text);

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

function invalidLiteral(text) {
  return new PyValueError(`invalid literal for int() with base 10: ${pyStrRepr(text)}`);
}

/**
 * `repr()` of a `str`, limited to what error messages need: the quote is
 * switched to `"` only when the text contains `'` but no `"`.
 */
export function pyStrRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === quote || ch === '\\') out += `\\${ch}`;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else {
      const cp = ch.codePointAt(0);
      if (cp < 0x20 || cp === 0x7f) out += `\\x${cp.toString(16).padStart(2, '0')}`;
      else out += ch;
    }
  }
  return out + quote;
}

