/**
 * Python `bytes` semantics.
 *
 * Byte strings are carried as Node `Buffer` values throughout the port; this
 * module supplies the two behaviours the script depends on: strict ASCII
 * encoding of a `str`, and `bytes.__repr__`.
 */

import { Buffer } from 'node:buffer';
import { PyUnicodeEncodeError } from './errors.mjs';

const QUOTE_SINGLE = 0x27;
const QUOTE_DOUBLE = 0x22;
const BACKSLASH = 0x5c;

/**
 * `text.encode('ascii')`.
 *
 * Raises `PyUnicodeEncodeError` on the first non-ASCII code point, reporting the
 * whole consecutive run of unencodable code points the way CPython's `ucs1`
 * encoder does. Positions are counted in code points, not UTF-16 units, so an
 * astral character occupies a single position.
 */
export function encodeAscii(text) {
  const codePoints = [...text];

  for (let i = 0; i < codePoints.length; i += 1) {
    if (codePoints[i].codePointAt(0) > 0x7f) {
      let end = i + 1;
      while (end < codePoints.length && codePoints[end].codePointAt(0) > 0x7f) end += 1;
      throw new PyUnicodeEncodeError('ascii', text, i, end, 'ordinal not in range(128)');
    }
  }

  return Buffer.from(codePoints.join(''), 'latin1');
}

/**
 * `repr()` of a `bytes` object.
 *
 * Mirrors CPython's `bytes_repr`: the delimiter becomes `"` only when the data
 * contains `'` and no `"` (so the quote never needs escaping), and bytes outside
 * the printable ASCII range fall back to lowercase `\xHH`.
 */
export function bytesRepr(buf) {
  const quote = buf.includes(QUOTE_SINGLE) && !buf.includes(QUOTE_DOUBLE)
    ? QUOTE_DOUBLE
    : QUOTE_SINGLE;

  let out = `b${String.fromCharCode(quote)}`;
  for (let i = 0; i < buf.length; i += 1) {
    const byte = buf[i];
    if (byte === quote || byte === BACKSLASH) out += `\\${String.fromCharCode(byte)}`;
    else if (byte === 0x09) out += '\\t';
    else if (byte === 0x0a) out += '\\n';
    else if (byte === 0x0d) out += '\\r';
    else if (byte < 0x20 || byte >= 0x7f) out += `\\x${byte.toString(16).padStart(2, '0')}`;
    else out += String.fromCharCode(byte);
  }
  return out + String.fromCharCode(quote);
}

/** Builds a `bytes` value from an ASCII source literal, e.g. `b'first'`. */
export function asciiBytes(literal) {
  return Buffer.from(literal, 'latin1');
}

