/**
 * `repr()` for the value graph the script prints: `bytes`, `int`, `list`, `dict`.
 *
 * `print(obj)` on a container calls `repr()` on the container, which recursively
 * uses `repr()` on the elements -- so a single renderer covers both the raw
 * `bytes` lines and the decoded structure line.
 */

import { Buffer } from 'node:buffer';
import { bytesRepr } from './bytes.mjs';
import { PyDict } from './dict.mjs';

export function pyRepr(value) {
  if (Buffer.isBuffer(value)) return bytesRepr(value);
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return String(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof PyDict) {
    const items = [...value.entries()].map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`);
    return `{${items.join(', ')}}`;
  }
  throw new TypeError(`pyRepr: unsupported value ${String(value)}`);
}

