 * An insertion-ordered mapping with `bytes` keys, standing in for a Python
 * `dict` keyed by byte strings.
 *
 * A plain `Map` cannot be used directly: `Buffer` keys compare by identity, so
 * two equal byte strings would occupy separate slots. Keys are therefore indexed
 * by their hex form while the canonical key objects keep insertion order --
 * matching Python, where re-assigning an existing key updates the value in place
 * without moving it.
 */

import { Buffer } from 'node:buffer';

export class PyDict {
  #order = [];
  #index = new Map();

  /** Builds a dict from `[keyBuffer, value]` pairs, applied in order. */
  static of(pairs) {
    const dict = new PyDict();
    for (const [key, value] of pairs) dict.set(key, value);
    return dict;
  }

  set(key, value) {
    const slot = key.toString('hex');
    const existing = this.#index.get(slot);
    if (existing === undefined) {
      this.#order.push(slot);
      this.#index.set(slot, { key: Buffer.from(key), value });
    } else {
      existing.value = value;
    }
    return this;
  }

  has(key) {
    return this.#index.has(key.toString('hex'));
  }

  get(key) {
    return this.#index.get(key.toString('hex'))?.value;
  }

  get size() {
    return this.#order.length;
  }

  /** Yields `[keyBuffer, value]` pairs in insertion order. */
  *entries() {
    for (const slot of this.#order) {
      const entry = this.#index.get(slot);
      yield [entry.key, entry.value];
    }
  }

  [Symbol.iterator]() {
    return this.entries();
  }
}

