/**
 * Bencode encoder.
 *
 * Grammar, as reproduced from the reference implementation's observable output:
 *   byte string  <decimal length> ":" <raw bytes>
 *   integer      "i" <decimal, optional leading "-"> "e"
 *   list         "l" <element>* "e"
 *   dictionary   "d" (<byte string key> <element>)* "e"
 *
 * Dictionary keys are emitted in ascending byte order regardless of insertion
 * order -- `{b'second': ..., b'number': ...}` encodes with `number` first.
 */

import { Buffer } from 'node:buffer';
import { PyDict } from '../py/dict.mjs';

/** Encodes `value` and returns the complete bencoded byte string. */
export function encode(value) {
  const chunks = [];
  emit(value, chunks);
  return Buffer.concat(chunks);
}

function emit(value, chunks) {
  if (Buffer.isBuffer(value)) {
    chunks.push(Buffer.from(`${value.length}:`, 'latin1'), value);
    return;
  }

  if (typeof value === 'bigint' || typeof value === 'number') {
    chunks.push(Buffer.from(`i${value.toString()}e`, 'latin1'));
    return;
  }

  if (Array.isArray(value)) {
    chunks.push(Buffer.from('l', 'latin1'));
    for (const item of value) emit(item, chunks);
    chunks.push(Buffer.from('e', 'latin1'));
    return;
  }

  if (value instanceof PyDict) {
    chunks.push(Buffer.from('d', 'latin1'));
    const entries = [...value.entries()].sort((a, b) => Buffer.compare(a[0], b[0]));
    for (const [key, item] of entries) {
      emit(key, chunks);
      emit(item, chunks);
    }
    chunks.push(Buffer.from('e', 'latin1'));
    return;
  }

  throw new TypeError(`encode: unsupported value ${String(value)}`);
}

