/**
 * Bencode decoder.
 *
 * Integers decode to BigInt (Python's `int` is unbounded), byte strings to
 * `Buffer`, lists to arrays, and dictionaries to `PyDict` so that the encoded
 * key order -- which is sorted -- is preserved for `repr()`.
 */

import { Buffer } from 'node:buffer';
import { PyDict } from '../py/dict.mjs';

const CH_i = 0x69;
const CH_l = 0x6c;
const CH_d = 0x64;
const CH_e = 0x65;
const CH_COLON = 0x3a;
const CH_MINUS = 0x2d;
const CH_0 = 0x30;
const CH_9 = 0x39;

/** Decodes a complete bencoded byte string. */
export function decode(data) {
  const buf = Buffer.isBuffer(data) ? data : Buffer.from(data, 'latin1');
  const reader = { buf, pos: 0 };
  const value = parse(reader);
  if (reader.pos !== buf.length) throw new Error('decode: trailing data after value');
  return value;
}

function parse(reader) {
  const { buf } = reader;
  if (reader.pos >= buf.length) throw new Error('decode: unexpected end of data');

  const marker = buf[reader.pos];
  if (marker === CH_i) return parseInteger(reader);
  if (marker === CH_l) return parseList(reader);
  if (marker === CH_d) return parseDict(reader);
  if (marker >= CH_0 && marker <= CH_9) return parseByteString(reader);
  throw new Error(`decode: unexpected token at offset ${reader.pos}`);
}

function parseInteger(reader) {
  reader.pos += 1; // past 'i'
  const start = reader.pos;
  if (reader.buf[reader.pos] === CH_MINUS) reader.pos += 1;
  while (isDigit(reader.buf[reader.pos])) reader.pos += 1;
  const text = reader.buf.toString('latin1', start, reader.pos);
  expect(reader, CH_e);
  if (text === '' || text === '-') throw new Error('decode: malformed integer');
  return BigInt(text);
}

function parseByteString(reader) {
  const start = reader.pos;
  while (isDigit(reader.buf[reader.pos])) reader.pos += 1;
  const length = Number(reader.buf.toString('latin1', start, reader.pos));
  expect(reader, CH_COLON);
  const end = reader.pos + length;
  if (end > reader.buf.length) throw new Error('decode: byte string runs past end of data');
  const value = Buffer.from(reader.buf.subarray(reader.pos, end));
  reader.pos = end;
  return value;
}

function parseList(reader) {
  reader.pos += 1; // past 'l'
  const items = [];
  while (reader.buf[reader.pos] !== CH_e) {
    if (reader.pos >= reader.buf.length) throw new Error('decode: unterminated list');
    items.push(parse(reader));
  }
  reader.pos += 1; // past 'e'
  return items;
}

function parseDict(reader) {
  reader.pos += 1; // past 'd'
  const dict = new PyDict();
  while (reader.buf[reader.pos] !== CH_e) {
    if (reader.pos >= reader.buf.length) throw new Error('decode: unterminated dictionary');
    const key = parseByteString(reader);
    dict.set(key, parse(reader));
  }
  reader.pos += 1; // past 'e'
  return dict;
}

function isDigit(byte) {
  return byte >= CH_0 && byte <= CH_9;
}

function expect(reader, byte) {
  if (reader.buf[reader.pos] !== byte) {
    throw new Error(`decode: expected '${String.fromCharCode(byte)}' at offset ${reader.pos}`);
  }
  reader.pos += 1;
}

