/**
 * A focused reimplementation of `argparse.ArgumentParser` covering the surface
 * the script uses: long options that always take one value, `required=True`,
 * `type=` conversion, the automatic `-h/--help` action, prefix abbreviation, and
 * argparse's exact usage/error wording and exit codes.
 *
 * Error precedence follows argparse: a `type` conversion failure is raised while
 * scanning, missing required options are reported at the end of
 * `parse_known_args`, and unrecognized arguments last of all.
 */

import { pyStrRepr } from '../py/int.mjs';

const EXIT_USAGE = 2;

class ArgumentError extends Error {}

export class ArgumentParser {
  #prog;
  #actions = [];

  constructor({ prog } = {}) {
    this.#prog = prog ?? 'prog';
    this.#actions.push({
      optionStrings: ['-h', '--help'],
      dest: 'help',
      isHelp: true,
      required: false,
      help: 'show this help message and exit',
    });
  }

  /**
   * Registers a long option. `type` is the converter applied to the raw string;
   * it may throw a Python-style exception, whose class name argparse folds into
   * the `invalid <name> value` message.
   */
  addArgument(optionString, { type, required = false, typeName } = {}) {
    const dest = optionString.replace(/^--?/, '').replace(/-/g, '_');
    this.#actions.push({
      optionStrings: [optionString],
      dest,
      metavar: dest.toUpperCase(),
      type,
      typeName: typeName ?? 'string',
      required,
      isHelp: false,
    });
    return this;
  }

  /** `usage: PROG [-h] --a A ...` without the trailing newline. */
  formatUsage() {
    const parts = this.#actions.map((action) => {
      const flag = action.optionStrings[action.optionStrings.length - 1];
      if (action.isHelp) return '[-h]';
      const body = `${flag} ${action.metavar}`;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${this.#prog} ${parts.join(' ')}`;
  }

  /**
   * Full `--help` text. The help column sits at `min(maxInvocation + 4, 24)`,
   * reproducing argparse's `HelpFormatter` layout for this option set.
   */
  formatHelp() {
    const invocations = this.#actions.map((action) => (
      action.isHelp
        ? action.optionStrings.join(', ')
        : `${action.optionStrings[0]} ${action.metavar}`
    ));
    const widest = Math.max(...invocations.map((text) => text.length));
    const helpColumn = Math.min(widest + 2 + 2, 24);

    const lines = [this.formatUsage(), '', 'options:'];
    this.#actions.forEach((action, i) => {
      const invocation = `  ${invocations[i]}`;
      if (!action.help) {
        lines.push(invocation);
      } else if (invocation.length < helpColumn) {
        lines.push(invocation + ' '.repeat(helpColumn - invocation.length) + action.help);
      } else {
        lines.push(invocation, ' '.repeat(helpColumn) + action.help);
      }
    });
    return `${lines.join('\n')}\n`;
  }

  /** Prints usage plus `PROG: error: <message>` to stderr and exits with 2. */
  error(message) {
    process.stderr.write(`${this.formatUsage()}\n`);
    process.stderr.write(`${this.#prog}: error: ${message}\n`);
    process.exit(EXIT_USAGE);
  }

  /** Parses `argv` (without the interpreter/script entries) into a namespace. */
  parseArgs(argv) {
    const { namespace, extras } = this.#parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  #parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.#actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];
    let optionsEnabled = true;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (optionsEnabled && token === '--') {
        optionsEnabled = false;
        continue;
      }

      // A lone '-' and anything not starting with '-' are positionals; this
      // parser defines none, so they become extras.
      if (!optionsEnabled || !token.startsWith('-') || token === '-' || token === '--') {
        extras.push(token);
        continue;
      }

      const eq = token.indexOf('=');
      const flag = eq === -1 ? token : token.slice(0, eq);
      const action = this.#resolve(flag);

      if (action === undefined) {
        extras.push(token);
        continue;
      }

      if (action.isHelp) {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      let raw;
      if (eq !== -1) {
        raw = token.slice(eq + 1);
      } else if (i + 1 < argv.length) {
        i += 1;
        raw = argv[i];
      } else {
        this.error(`argument ${flag}: expected one argument`);
      }

      try {
        namespace[action.dest] = action.type ? action.type(raw) : raw;
      } catch {
        this.error(`argument ${flag}: invalid ${action.typeName} value: ${pyStrRepr(raw)}`);
      }
      seen.add(action.dest);
    }

    const missing = this.#actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /**
   * Maps a flag to its action, allowing unambiguous prefixes (argparse's default
   * `allow_abbrev=True`), e.g. `--h` resolves to `--help`.
   */
  #resolve(flag) {
    const exact = this.#actions.find((action) => action.optionStrings.includes(flag));
    if (exact !== undefined) return exact;

    if (!flag.startsWith('--')) return undefined;

    const candidates = [];
    for (const action of this.#actions) {
      for (const optionString of action.optionStrings) {
        if (optionString.startsWith('--') && optionString.startsWith(flag)) {
          candidates.push({ action, optionString });
        }
      }
    }
    if (candidates.length === 1) return candidates[0].action;
    if (candidates.length > 1) {
      const options = candidates.map((candidate) => candidate.optionString).join(', ');
      this.error(`ambiguous option: ${flag} could match ${options}`);
    }
    return undefined;
  }
}

export { ArgumentError };

