/**
 * Node port of `test12.py`.
 *
 * Builds two byte-keyed dictionaries from the command line, bencodes them both
 * together (as a list) and separately, decodes the combined form, and prints all
 * four values using Python's `repr()` formatting.
 */

import { basename } from 'node:path';
import * as bencoder from './lib/bencode/index.mjs';
import { ArgumentParser } from './lib/cli/argparse.mjs';
import { PyDict } from './lib/py/dict.mjs';
import { asciiBytes, encodeAscii } from './lib/py/bytes.mjs';
import { formatTraceback, PyException } from './lib/py/errors.mjs';
import { pyInt } from './lib/py/int.mjs';
import { pyRepr } from './lib/py/repr.mjs';

/**
 * The two source lines that can raise, with the sub-expression CPython
 * underlines, so an `ascii` encoding failure reproduces the original traceback.
 */
const FRAMES = {
  dict1: frame(10, "dict1 = {b'first': args.a.encode('ascii')}", "args.a.encode('ascii')"),
  dict2: frame(11, "dict2 = {b'second': args.b.encode('ascii'), b'number': args.c}", "args.b.encode('ascii')"),
};

function frame(line, text, expression) {
  return {
    file: 'test12.py',
    line,
    text,
    caretColumn: text.indexOf(expression),
    caretLength: expression.length,
  };
}

function buildParser(prog) {
  const parser = new ArgumentParser({ prog });
  parser.addArgument('--a', { type: String, required: true });
  parser.addArgument('--b', { type: String, required: true });
  parser.addArgument('--c', { type: pyInt, required: true, typeName: 'int' });
  return parser;
}

function main(argv) {
  const args = buildParser(basename(argv[1] ?? 'test12.mjs')).parseArgs(argv.slice(2));

  let dict1;
  let dict2;
  try {
    dict1 = PyDict.of([[asciiBytes('first'), encodeAscii(args.a)]]);
  } catch (err) {
    return fail(err, FRAMES.dict1);
  }
  try {
    dict2 = PyDict.of([
      [asciiBytes('second'), encodeAscii(args.b)],
      [asciiBytes('number'), args.c],
    ]);
  } catch (err) {
    return fail(err, FRAMES.dict2);
  }

  const combined = [dict1, dict2];
  const encoded = bencoder.encode(combined); // Encode list of dictionaries
  const decoded = bencoder.decode(encoded); // Decode list of dictionaries
  const encodedDict1 = bencoder.encode(dict1); // Encode first dictionary separately
  const encodedDict2 = bencoder.encode(dict2); // Encode second dictionary separately

  console.log(pyRepr(encoded));
  console.log(pyRepr(decoded));
  console.log(pyRepr(encodedDict1));
  console.log(pyRepr(encodedDict2));
  return 0;
}

/** Reproduces an unhandled Python exception: traceback on stderr, status 1. */
function fail(err, frameInfo) {
  if (!(err instanceof PyException)) throw err;
  process.stderr.write(formatTraceback([frameInfo], err));
  return 1;
}

process.exitCode = main(process.argv);

