/**
 * The slice of CPython's `linecache` that traceback rendering depends on.
 *
 * A traceback shows the offending source line only when the module's file can
 * still be read relative to the process's working directory. When it cannot --
 * the usual case for a distributed build -- CPython silently omits both the
 * source line and the caret line, and this module reproduces that by returning
 * an empty string.
 */

import { readFileSync } from 'node:fs';

/** Returns line `lineNumber` (1-based) of `filename`, or '' if unavailable. */
export function getLine(filename, lineNumber) {
  let text;
  try {
    text = readFileSync(filename, 'utf8');
  } catch {
    return '';
  }
  // Python opens source with universal newlines, so any of the three
  // line-ending conventions terminates a line.
  const lines = text.split(/\r\n|\n|\r/);
  return lines[lineNumber - 1] ?? '';
}

