/**
 * Renders a CPython traceback for `exc` over `frames` and returns it as a
 * string, including the trailing newline that `sys.excepthook` emits.
 *
 * Each frame is `{ file, line, name, caretColumn, caretLength }`. The source
 * line is looked up through `linecache`, so it is shown only when the file is
 * readable from the working directory; `caretColumn` is the column recorded in
 * the code object (PEP 657) and is rebased onto the stripped line.
 */
export function formatTraceback(frames, exc) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name ?? '<module>'}`);

    const raw = getLine(frame.file, frame.line);
    const stripped = raw.trim();
    if (stripped === '') continue;

    lines.push(`    ${stripped}`);

    const column = frame.caretColumn - (raw.length - raw.trimStart().length);
    // Carets are suppressed when they would underline the entire line, since
    // that adds no information.
    const underlinesWholeLine = column === 0 && frame.caretLength === stripped.length;
    if (frame.caretLength > 0 && column >= 0 && !underlinesWholeLine) {
      lines.push(`    ${' '.repeat(column)}${'^'.repeat(frame.caretLength)}`);
    }
  }
  lines.push(exc.formatExceptionOnly());
  return `${lines.join('\n')}\n`;
}

