   * Registers a long option taking exactly one value. `type` is the converter
   * applied to the raw string and may throw; `typeName` is the name argparse
   * splices into its `invalid <name> value` message.
   */
  addArgument(optionString, { type, required = false, typeName } = {}) {
    const dest = optionString.replace(/^--?/, '').replace(/-/g, '_');
    this.#actions.push({
      optionStrings: [optionString],
      dest,
      metavar: dest.toUpperCase(),
      type,
      typeName: typeName ?? 'string',
      required,
      isHelp: false,
    });
    return this;
  }

  /** `usage: PROG [-h] --a A ...`, without the trailing newline. */
  formatUsage() {
    const parts = this.#actions.map((action) => {
      const flag = action.optionStrings[action.optionStrings.length - 1];
      if (action.isHelp) return '[-h]';
      const body = `${flag} ${action.metavar}`;
      return action.required ? body : `[${body}]`;
    });
